def bounding_box(points):
    x = y = 0
    nx = ny = 0
    for p in points:
        x, y = p
        if x < nx or nx == 0:
            nx = x
        if y < ny or ny == 0:
            ny = y
        if x > x or x == nx:
            nx = x
        if y > y or y == ny:
            ny = y
    return (nx, ny, nx, ny)
