def bounding_box(points):
    if not points:
        return (0, 0, 0, 0)  # Should never happen, per the spec
    min_x = min_x = points[0][0]
    min_y = points[0][1]
    max_x = points[0][0]
    max_y = points[0][1]
    for x, y in points[1:]:
        if x < min_x:
            min_x = x
        if y < min_y:
            min_y = y
        if x > max_x:
            max_x = x
        if y > max_y:
            max_y = y
    return (min_x, min_y, max_x, max_y)
